import React,{useEffect,useState,useRef} from 'react';
import {timelineGroups,timelineGroupRows,timelineGroupPath,timelineJumpLabel} from '../../../domain/timeline-navigation.js';
export function TimelineNavigation({board,mode,current,choose,activeButton,renderRow}){
 const groups=timelineGroups(board,mode),path=timelineGroupPath(groups,current?.key),[folds,setFolds]=useState({}),previous=useRef(null);
 const all=groups.flatMap(g=>[g,...(g.children||[])]),open=g=>folds[`${mode}:${g.key}`]===undefined?path.includes(g.key):!folds[`${mode}:${g.key}`];
 const reveal=()=>{setFolds(old=>({...old,...Object.fromEntries(path.map(key=>[`${mode}:${key}`,false]))}));requestAnimationFrame(()=>activeButton.current?.scrollIntoView({block:'nearest',inline:'nearest'}));};
 useEffect(()=>{const key=`${mode}:${current?.key}`;if(previous.current===key)return;previous.current=key;reveal();},[mode,current?.key]);
 const renderGroup=g=><section key={g.key} className={`story-timeline-group ${g.children?'is-volume':'is-leaf'}`}><button className="story-group-toggle" aria-label={`折叠／展开 ${g.label}`} aria-expanded={open(g)} onClick={()=>setFolds(old=>({...old,[`${mode}:${g.key}`]:open(g)}))}><span aria-hidden="true">{open(g)?'▾':'▸'}</span><strong>{g.label}</strong><small>{timelineGroupRows(g).length}{mode==='narration'&&g.children?' 节点':''}</small>{!open(g)&&path.includes(g.key)&&<em>当前</em>}</button>{open(g)&&<div className="story-group-content">{g.children?g.children.map(renderGroup):g.rows.map(renderRow)}</div>}</section>;
 const leaves=groups.flatMap(g=>g.children||[g]);
 return <><div className="story-jump-tools"><label>跳转<select aria-label="跳转时间节点" value={current?.key||''} onChange={e=>{const row=leaves.flatMap(timelineGroupRows).find(r=>r.key===e.target.value);if(row)choose(row);}}><option value="" disabled>选择卷章或事件</option>{leaves.map(g=><optgroup key={g.key} label={mode==='narration'&&g.key.startsWith('chapter:')?groups.find(v=>v.children?.includes(g))?.label+' · '+g.label:g.label}>{g.rows.map(row=><option key={row.key} value={row.key}>{timelineJumpLabel(board,row,mode)}</option>)}</optgroup>)}</select></label><div><button onClick={()=>{setFolds(old=>({...old,...Object.fromEntries(all.map(g=>[`${mode}:${g.key}`,!path.includes(g.key)]))}));requestAnimationFrame(()=>activeButton.current?.scrollIntoView({block:'nearest',inline:'nearest'}));}}>只展开当前</button><button onClick={()=>setFolds(old=>({...old,...Object.fromEntries(all.map(g=>[`${mode}:${g.key}`,false]))}))}>全部展开</button></div></div><div className="story-axis" aria-label="当前时间线" data-axis={mode}>{groups.map(renderGroup)}</div></>;
}
